package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.repository.jobs.JdbcFrozenInputs;
import com.lianxibu.site.service.articles.CatalogVersionQualificationService;
import com.lianxibu.site.service.jobs.ResultApplicationService.Input;
import java.util.*;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.node.*;
import tools.jackson.databind.json.JsonMapper;

/** Native single/all-old-member proof issuer. Serialized batch expansion tests are pure and grant no native authority. */
class FrozenCatalogVersionProjectionsTest extends CatalogVersionJudgmentValueTest {
    @Test void FourCategoriesFreezeCompleteNativeProofAndTypedSidesWithoutSharingMutableTrees(){for(String category:List.of("agent","skill","workflow","model")){initialize(category,false);var p=projection();var frozen=FrozenCatalogVersionProjections.create(List.of(p),input(p));var entry=frozen.entries().get(p.memberId());assertEquals(p.json(),entry.json());assertTrue(entry.matches(p));assertEquals(p.judgmentKey(),entry.judgmentKey());assertEquals(p.hash(),entry.hash());assertEquals(p.contentId(),entry.contentId());var modified=(ObjectNode)frozen.toJson();((ObjectNode)modified.get("items").get(0).get("projection")).put("entity_generation",99);assertEquals(p.json(),entry.json());assertThrows(RuntimeException.class,()->frozen.entries().clear());assertFalse(entry.toString().contains("fictional"));assertEquals(1,f.sends);}}
    @Test void ActualHundredOriginalMembersKeepAllRefsAndHashesInTheFrozenFrame(){var large=new CatalogPreviousVersionProfileTest.Fixture(){@Override ObjectNode catalogPayload(){return super.catalogPayload().put("summary","Fictional complete old body "+"x".repeat(8000));}};large.members=100;large.initializeCatalog(mysql(),"agent",true);f=large;current=f.catalogPayload();current.put("version","v2");((ObjectNode)current.get("evidence").get(0)).put("revision","v2");f.jdbc.update("INSERT INTO source_run_items VALUES('fictional-current-item','fictional-run','fictional-source',3,'agent',?,'accepted','pending','initialized',1,?,?,NULL,'fictional-current-source-item')",java.sql.Timestamp.from(f.clock.instant().minusSeconds(1)),JdbcFrozenInputs.canonical(current),HexFormat.of().parseHex(CatalogPreviousAnalysisTest.Fixture.sha(CanonicalJson.bytes(current))));service=new CatalogVersionQualificationService(f.source,f.tx);var p=projection();var frozen=FrozenCatalogVersionProjections.create(List.of(p),input(p));assertEquals(100,CanonicalJson.parse(frozen.entries().get(p.memberId()).json()).get("previous_proof").get("members").size());assertTrue(frozen.json().contains("fictional-item-99"));assertTrue(read().orElseThrow().previous().evidence().previous().inputJson().length()>800000);assertFalse(frozen.json().contains("Fictional complete old body"));assertEquals(1,f.sends);}
    @Test void KnownFalseRemainsPresentWhileUnknownHasNoManufacturedFalseProjection(){current=f.catalogPayload();update();var p=projection();assertFalse(p.versionChanged());assertEquals(1,FrozenCatalogVersionProjections.create(List.of(p),input(p)).entries().size());var i=input(p);var empty=new Input(i.rootId(),i.attemptId(),i.stage(),i.generation(),i.inputHash(),i.expectedRootRevision(),i.expectedContentRevision(),i.itemIds(),i.candidatesByItem(),i.eligibleHighValueItems(),i.allowedCitationIds(),Set.of(),i.targetEntityId(),i.periodStart(),i.periodEnd(),i.valueResultVersion(),i.dedupResultVersion(),Map.of());assertTrue(FrozenCatalogVersionProjections.create(List.of(),empty).entries().isEmpty());assertThrows(RuntimeException.class,()->FrozenCatalogVersionProjections.create(List.of(p),empty));assertThrows(RuntimeException.class,()->FrozenCatalogVersionProjections.create(List.of(),i));}
    @Test void RehashedWrongOldCurrentRoleAndUnknownFieldsCannotReplaceFrozenSides(){var p=projection();var i=input(p);for(String fault:List.of("old_root","old_member","current_entity","marker","time","gen","extra")){var frame=(ObjectNode)FrozenCatalogVersionProjections.create(List.of(p),i).toJson();var row=(ObjectNode)frame.get("items").get(0);var proof=(ObjectNode)row.get("projection");switch(fault){case "old_root"->((ObjectNode)proof.get("previous_proof")).put("root_id","fictional-foreign");case "old_member"->((ObjectNode)proof.get("previous_proof").get("members").get(0)).put("version_hash","f".repeat(64));case "current_entity"->((ObjectNode)proof.get("current_proof")).put("entity_id","fictional-foreign");case "marker"->((ObjectNode)proof.get("current_marker").get("version")).put("version","v9");case "time"->proof.put("cutoff","2025-01-01T00:00:00.000000Z");case "gen"->proof.put("entity_generation",0);case "extra"->proof.put("unexpected",true);}row.put("projection_hash",CanonicalJson.hash(CanonicalJson.Domain.INPUT,proof));assertThrows(RuntimeException.class,()->FrozenCatalogVersionProjections.read(frame,i));}current.put("summary","Fictional later metadata");update();assertFalse(FrozenCatalogVersionProjections.create(List.of(p),i).entries().get(p.memberId()).matches(projection()));}
    @Test void FullPureHundredBatchHasNoTruncationAndBadLastDuplicateMissingOrBudgetOverflowRejects(){var p=projection();var base=input(p);var frame=JsonMapper.shared().createObjectNode().put("schema_version","catalog-version-projections-v1");var rows=frame.putArray("items");var items=new TreeSet<String>();var candidates=new HashMap<String,Set<String>>();var qualifications=new HashMap<String,FrozenCatalogVersionQualifications.Qualification>();for(int n=0;n<100;n++){String id=String.format(Locale.ROOT,"fictional-current-%03d",n);var proof=(ObjectNode)p.toJson();proof.put("item_id",id);((ObjectNode)proof.get("current_proof")).put("item_id",id);var row=rows.addObject().put("projection_hash",CanonicalJson.hash(CanonicalJson.Domain.INPUT,proof));row.set("projection",proof);items.add(id);candidates.put(id,Set.of(p.entityId()));qualifications.put(id,new FrozenCatalogVersionQualifications.Qualification(id,p.entityId(),true,p.resultConstraint().previousProofHash(),CanonicalJson.hash(CanonicalJson.Domain.INPUT,proof.get("current_proof"))));}var i=new Input(base.rootId(),base.attemptId(),base.stage(),base.generation(),base.inputHash(),base.expectedRootRevision(),base.expectedContentRevision(),Set.copyOf(items),Map.copyOf(candidates),Set.of(),Set.of(),Set.copyOf(items),null,null,null,"1","2",Map.copyOf(qualifications));var full=FrozenCatalogVersionProjections.read(frame,i);assertEquals(100,full.entries().size());assertTrue(full.entries().containsKey("fictional-current-099"));assertFalse(full.entries().get("fictional-current-099").matches(p));var bad=frame.deepCopy();((ObjectNode)bad.get("items").get(99)).put("projection_hash","f".repeat(64));assertThrows(RuntimeException.class,()->FrozenCatalogVersionProjections.read(bad,i));var missing=frame.deepCopy();((ArrayNode)missing.get("items")).remove(99);assertThrows(RuntimeException.class,()->FrozenCatalogVersionProjections.read(missing,i));var duplicate=frame.deepCopy();((ArrayNode)duplicate.get("items")).set(99,duplicate.get("items").get(0));assertThrows(RuntimeException.class,()->FrozenCatalogVersionProjections.read(duplicate,i));var wide=frame.deepCopy();wide.put("fictional_padding","x".repeat(FrozenCatalogVersionProjections.MAX_BYTES));assertThrows(GenerationFlowService.CapacityGuarded.class,()->FrozenCatalogVersionProjections.read(wide,i));assertEquals(1,f.sends);}
}
